import { Component, OnInit, OnDestroy } from '@angular/core';
import { ProjectService, Project } from '../../../core/services/project.service';
import { AuthService } from '../../../core/services/auth.service';
import { ProjectDocumentService } from '../../../core/services/project-document.service';
import { ProjectDocument, ProjectDocumentForm, ProjectDocumentType } from '../../../core/models/project-document.model';
import { UserService } from '../../../core/services/user.service';
import { MessageService, ConfirmationService } from 'primeng/api';
import { Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'app-project-list',
  templateUrl: './project-list.component.html',
  styleUrl: './project-list.component.scss'
})
export class ProjectListComponent implements OnInit, OnDestroy {
  projects: Project[] = [];
  loading = false;
  selectedProject: Project | null = null;
  displayDetailDialog = false;
  displayCreateDialog = false;
  displayEditDialog = false;
  displayDeleteDialog = false;
  private destroy$ = new Subject<void>();

  // Date validation
  today = new Date();

  searchTerm = '';
  statusFilter = '';
  statusOptions = [
    { label: 'All Status', value: '' },
    { label: 'Planned', value: 'PLANNED' },
    { label: 'In Progress', value: 'IN_PROGRESS' },
    { label: 'Completed', value: 'COMPLETED' },
    { label: 'On Hold', value: 'ON_HOLD' },
    { label: 'Cancelled', value: 'CANCELLED' }
  ];

  // Advanced search filters
  advancedSearchActive = false;
  advancedFilters = {
    name: '',
    status: '',
    description: '',
    customer: '',
    createdBy: '',
    minProgress: null,
    maxProgress: null,
    startDateFrom: null,
    startDateTo: null,
    delayedOnly: false,
    sortBy: 'CREATED_DATE',
    sortDirection: 'DESC'
  };

  // Standard/General sort options that everyone knows
  sortOptions = [
    { label: ' Most Recent First', value: 'CREATED_DATE' },
    { label: ' Oldest First', value: 'CREATED_DATE_ASC' },
    { label: ' Project Name (A-Z)', value: 'NAME' },
    { label: ' Project Name (Z-A)', value: 'NAME_DESC' },
    { label: '⏳ Start Date (Earliest)', value: 'START_DATE' },
    { label: '⏳ Start Date (Latest)', value: 'START_DATE_DESC' },
    { label: ' Progress (Highest)', value: 'PROGRESS' },
    { label: ' Progress (Lowest)', value: 'PROGRESS_ASC' },
    { label: ' Recently Updated', value: 'UPDATED_DATE' },
    { label: '⏱️ Status (A-Z)', value: 'STATUS' }
  ];

  sortDirectionOptions = [
    { label: '⬆️ Ascending', value: 'ASC' },
    { label: '⬇️ Descending', value: 'DESC' }
  ];

  newProject: Partial<Project> = {
    name: '',
    description: '',
    objectives: '',
    startDate: new Date().toISOString().split('T')[0],
    endDate: '',
    visibility: 'PRIVATE'
  };

  touchedFields: { [key: string]: boolean } = {
    name: false,
    description: false,
    objectives: false,
    startDate: false,
    endDate: false
  };

  // Pagination
  private currentPage = 1;
  itemsPerPage = 6;
  rowsPerPageOptions = [6, 10, 20, 30];
  paginatedProjects: Project[] = [];
  totalRecords = 0;
  availableRoles = [
    { label: 'Project Member', value: 'PROJECT_MEMBER' },
    { label: 'Project Manager', value: 'PROJECT_MANAGER' },
    { label: 'Customer', value: 'CUSTOMER' }
  ];

  // Member management
  newMemberEmail = '';
  newMemberRole = 'PROJECT_MEMBER';
  selectedNewMember: any = null;
  allUsers: any[] = [];
  filteredUsers: any[] = [];
  projectMembersToAdd: any[] = [];

  // Customer selection
  selectedCustomer: any = null;
  allCustomers: any[] = [];
  filteredCustomers: any[] = [];

  // Document management
  projectDocuments: ProjectDocument[] = [];
  filteredProjectDocuments: ProjectDocument[] = [];
  documentSearchTerm = '';
  documentTypeFilter = '';
  editingDocumentId: number | null = null;
  pendingDocumentEditIndex: number | null = null;
  pendingDocuments: ProjectDocumentForm[] = [];
  projectDocumentTypes: { label: string; value: ProjectDocumentType | '' }[] = [
    { label: 'All Types', value: '' },
    { label: 'Cahier des charges', value: 'CAHIER_CHARGES' },
    { label: 'Specifications', value: 'SPECIFICATIONS' },
    { label: 'Architecture', value: 'ARCHITECTURE' },
    { label: 'Design', value: 'DESIGN' },
    { label: 'Test plan', value: 'TEST_PLAN' },
    { label: 'Documentation', value: 'DOCUMENTATION' },
    { label: 'Release notes', value: 'RELEASE_NOTES' },
    { label: 'Other', value: 'OTHER' }
  ];
  projectDocumentTypeOptions = this.projectDocumentTypes.filter(option => option.value !== '');
  documentForm!: ProjectDocumentForm;

   constructor(
     private projectService: ProjectService,
     private projectDocumentService: ProjectDocumentService,
     public authService: AuthService,
     private userService: UserService,
     private messageService: MessageService,
     private confirmationService: ConfirmationService
   ) {
     this.documentForm = this.buildEmptyDocumentForm();
   }

  ngOnInit(): void {
    this.loadProjects();
    this.loadCustomers();
    this.loadUsers();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  loadProjects(): void {
    this.loading = true;
    const currentUser = this.authService.getCurrentUser();

    if (!currentUser) {
      this.messageService.add({
        severity: 'error',
        summary: 'Error',
        detail: 'User not authenticated'
      });
      this.loading = false;
      return;
    }

    this.projectService.getProjectsByUser(currentUser.id.toString())
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (data) => {
          this.projects = data;
          this.totalRecords = data.length;
          this.updatePaginatedProjects(0);
          this.loading = false;
        },
        error: (error) => {
          console.error('Error loading projects', error);
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: 'Failed to load projects'
          });
          this.loading = false;
        }
      });
  }

  performSearch(): void {
    if (!this.searchTerm && !this.statusFilter) {
      this.loadProjects();
      return;
    }

    this.loading = true;
    this.projectService.searchProjects(this.searchTerm, this.statusFilter)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (data) => {
          this.projects = data;
          this.totalRecords = data.length;
          this.updatePaginatedProjects(0);
          this.loading = false;
        },
        error: (error) => {
          console.error('Error searching projects', error);
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: 'Failed to search projects'
          });
          this.loading = false;
        }
      });
  }

  toggleAdvancedSearch(): void {
    this.advancedSearchActive = !this.advancedSearchActive;
    if (!this.advancedSearchActive) {
      this.resetAdvancedFilters();
    }
  }

  performAdvancedSearch(): void {
    this.loading = true;
    const filters = {
      ...this.advancedFilters,
      minProgress: this.advancedFilters.minProgress ? this.advancedFilters.minProgress / 100 : null,
      maxProgress: this.advancedFilters.maxProgress ? this.advancedFilters.maxProgress / 100 : null
    };

    this.projectService.advancedSearchProjects(filters)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (data) => {
          this.projects = data;
          this.totalRecords = data.length;
          this.updatePaginatedProjects(0);
          this.loading = false;
          this.messageService.add({
            severity: 'success',
            summary: 'Success',
            detail: `Found ${data.length} project(s)`
          });
        },
        error: (error) => {
          console.error('Error searching projects', error);
          this.loading = false;
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: 'Failed to perform advanced search'
          });
        }
      });
  }

  resetAdvancedFilters(): void {
    this.advancedFilters = {
      name: '',
      status: '',
      description: '',
      customer: '',
      createdBy: '',
      minProgress: null,
      maxProgress: null,
      startDateFrom: null,
      startDateTo: null,
      delayedOnly: false,
      sortBy: 'CREATED_DATE',
      sortDirection: 'DESC'
    };
    this.loadProjects();
  }

  onStatusFilterChange(): void {
    this.performSearch();
  }

  clearFilters(): void {
    this.searchTerm = '';
    this.statusFilter = '';
    this.loadProjects();
  }

    /**
     * Load customers from user service or mock data
     */
    loadCustomers(): void {
      // Load customers from backend using the /all endpoint (no pagination)
      this.userService.getAllUsersList()
        .pipe(takeUntil(this.destroy$))
        .subscribe({
          next: (usersList: any[]) => {
            console.log('Customers response:', usersList);

            // Convert to the format we need
            this.allCustomers = usersList
              .map((user: any) => {
                // Ensure firstName and lastName are always defined
                const firstName = (user.firstName || user.name || user.username || 'User').toString().trim();
                const lastName = (user.lastName || '').toString().trim();
                const fullName = `${firstName} ${lastName}`.trim();

                return {
                  id: user.id,
                  username: user.username,
                  email: user.email,
                  firstName: firstName,
                  lastName: lastName,
                  avatar: user.avatarUrl || user.avatar,
                  fullName: fullName
                };
              });

            this.filteredCustomers = [...this.allCustomers];

            // Sort by username
            this.filteredCustomers.sort((a, b) => a.username.localeCompare(b.username));
          },
          error: (error) => {
            console.error('Error loading customers:', error);
            // Fallback to empty list on error
            this.allCustomers = [];
            this.filteredCustomers = [];
          }
        });
    }

  /**
   * Filter customers based on search term (username)
   */
  filterCustomers(event: any): void {
    const query = event.query;
    this.filteredCustomers = this.allCustomers.filter(customer =>
      customer.username.toLowerCase().includes(query.toLowerCase()) ||
      customer.email.toLowerCase().includes(query.toLowerCase())
    );
    // Sort by username
    this.filteredCustomers.sort((a, b) => a.username.localeCompare(b.username));
  }

  /**
   * Handle customer selection
   */
  onCustomerSelect(event: any): void {
    this.selectedCustomer = event;
  }

   /**
    * Load users from user service or mock data
    * Excludes the currently logged-in user
    */
   loadUsers(): void {
     const currentUser = this.authService.getCurrentUser();

     // Load users from backend using the /all endpoint (no pagination)
     this.userService.getAllUsersList()
       .pipe(takeUntil(this.destroy$))
       .subscribe({
         next: (usersList: any[]) => {
           // Debug: log what we receive
           console.log('Users response:', usersList);

           // Convert to the format we need and filter out current user
           this.allUsers = usersList
             .map((user: any) => {
               console.log('Processing user:', user);

               // Ensure firstName and lastName are always defined
               const firstName = (user.firstName || user.name || user.username || 'User').toString().trim();
               const lastName = (user.lastName || '').toString().trim();
               const fullName = `${firstName} ${lastName}`.trim();

               const mappedUser = {
                 id: user.id,
                 username: user.username,
                 email: user.email,
                 firstName: firstName,
                 lastName: lastName,
                 avatar: user.avatarUrl || user.avatar,
                 fullName: fullName
               };

               console.log('Mapped user:', mappedUser);
               return mappedUser;
             })
             .filter((user: any) => user.id !== currentUser?.id);

           console.log('All users after mapping:', this.allUsers);

           this.filteredUsers = [...this.allUsers];

           // Sort by first name
           this.filteredUsers.sort((a, b) => a.firstName.localeCompare(b.firstName));
         },
         error: (error) => {
           console.error('Error loading users:', error);
           // Fallback to empty list on error
           this.allUsers = [];
           this.filteredUsers = [];
           this.messageService.add({
             severity: 'warn',
             summary: 'Warning',
             detail: 'Could not load users list from server'
           });
         }
       });
   }

  /**
   * Filter users based on search term (firstName, lastName, username, or email)
   */
  filterUsers(event: any): void {
    const query = event.query.toLowerCase();
    this.filteredUsers = this.allUsers.filter(user =>
      user.firstName.toLowerCase().includes(query) ||
      user.lastName.toLowerCase().includes(query) ||
      user.username.toLowerCase().includes(query) ||
      user.email.toLowerCase().includes(query)
    );
    // Sort by first name
    this.filteredUsers.sort((a, b) => a.firstName.localeCompare(b.firstName));
  }

   /**
    * Get display name for a user
    */
   getUserDisplayName(user: any): string {
     if (!user) return '';
     const firstName = user.firstName || user.name || user.username || '';
     const lastName = user.lastName || '';
     const fullName = `${firstName} ${lastName}`.trim();
     return fullName || user.username || user.email || 'User';
   }

   /**
    * Handle member selection
    */
   onMemberSelect(event: any): void {
     this.selectedNewMember = event?.value ?? event;
   }

   /**
    * Add member to the temporary list during project creation
    */
   addMemberToCreateForm(): void {
     if (!this.selectedNewMember) {
       this.messageService.add({
         severity: 'error',
         summary: 'Error',
         detail: 'Please select a user'
       });
       return;
     }

     // Check if member already in the list
     const exists = this.projectMembersToAdd.some(m => m.id === this.selectedNewMember.id);
     if (exists) {
       this.messageService.add({
         severity: 'warning',
         summary: 'Warning',
         detail: 'This user is already in the members list'
       });
       return;
     }

     // Add member to the list
     this.projectMembersToAdd.push({
       id: this.selectedNewMember.id,
       firstName: this.selectedNewMember.firstName,
       lastName: this.selectedNewMember.lastName,
       username: this.selectedNewMember.username,
       email: this.selectedNewMember.email,
       role: this.newMemberRole,
       fullName: this.selectedNewMember.fullName
     });

     this.messageService.add({
       severity: 'success',
       summary: 'Success',
       detail: `${this.selectedNewMember.fullName} added to members list`
     });

     // Reset selections
     this.selectedNewMember = null;
     this.newMemberRole = 'PROJECT_MEMBER';
   }

  /**
   * Remove member from the temporary list during project creation
   */
  removeMemberFromCreateForm(member: any): void {
    this.projectMembersToAdd = this.projectMembersToAdd.filter(m => m.id !== member.id);
    this.messageService.add({
      severity: 'info',
      summary: 'Removed',
      detail: `${member.firstName} removed from members list`
    });
  }

   /**
    * Add members to the created project
    */
   private addMembersToCreatedProject(createdProject: any, onComplete: () => void): void {
      let membersAdded = 0;
      let membersTotal = this.projectMembersToAdd.length;

      if (membersTotal === 0) {
        onComplete();
        return;
      }

      this.projectMembersToAdd.forEach((member) => {
        // Use username instead of ID to match backend expectation
        this.projectService.addProjectMember(createdProject.id, member.username, member.role)
          .pipe(takeUntil(this.destroy$))
          .subscribe({
            next: () => {
              membersAdded++;
              if (membersAdded === membersTotal) {
                onComplete();
              }
            },
            error: (error) => {
              console.error(`Error adding member ${member.firstName}:`, error);
              membersAdded++;
              if (membersAdded === membersTotal) {
                onComplete();
              }
            }
          });
      });
    }

   private addDocumentsToCreatedProject(createdProject: any, onComplete: () => void): void {
     let documentsAdded = 0;
     const documentsTotal = this.pendingDocuments.length;

     if (documentsTotal === 0) {
       onComplete();
       return;
     }

     this.pendingDocuments.forEach((document) => {
       this.projectDocumentService.create(createdProject.id, document)
         .pipe(takeUntil(this.destroy$))
         .subscribe({
           next: () => {
             documentsAdded++;
             if (documentsAdded === documentsTotal) {
               onComplete();
             }
           },
           error: (error) => {
             console.error('Error adding document to created project:', error);
             documentsAdded++;
             if (documentsAdded === documentsTotal) {
               onComplete();
             }
           }
         });
     });
   }

   /**
    * Complete project creation process
    */
   private completeProjectCreation(createdProject: any, membersCount?: number, documentsCount?: number): void {
     let detail = `Project created successfully`;
     if (membersCount && membersCount > 0) {
       detail += ` with ${membersCount} member(s) added`;
     }
     if (documentsCount && documentsCount > 0) {
       detail += `${membersCount && membersCount > 0 ? ' and' : ' with'} ${documentsCount} document(s) added`;
     }

     this.messageService.add({
       severity: 'success',
       summary: 'Success',
       detail: detail
     });

     this.displayCreateDialog = false;
     this.selectedCustomer = null;
     this.projectMembersToAdd = [];
     this.pendingDocuments = [];
     this.resetDocumentForm();
     this.loading = false;

     // Reload projects after a short delay to ensure backend has persisted
     setTimeout(() => this.loadProjects(), 500);
  }

  isProjectManager(project: Project): boolean {
    const currentUser = this.authService.getCurrentUser();
    return currentUser !== null && project.projectManagerId === currentUser.id.toString();
  }

  canEdit(project: Project): boolean {
    return this.isProjectManager(project);
  }

  canDelete(project: Project): boolean {
    return this.isProjectManager(project) && project.status !== 'COMPLETED';
  }

  formatDate(date: string | undefined): string {
    if (!date) return '-';
    return new Date(date).toLocaleDateString();
  }

  getDocumentTypeLabel(type: string): string {
    const labels: Record<string, string> = {
      CAHIER_CHARGES: 'Cahier des charges',
      SPECIFICATIONS: 'Specifications',
      ARCHITECTURE: 'Architecture',
      DESIGN: 'Design',
      TEST_PLAN: 'Test plan',
      DOCUMENTATION: 'Documentation',
      RELEASE_NOTES: 'Release notes',
      OTHER: 'Other'
    };
    return labels[type] || type;
  }

  // Convert string date to Date object for calendar minDate
  getStartDateAsDate(): Date | null {
    if (!this.newProject.startDate) return null;
    return new Date(this.newProject.startDate as string);
  }

  onSelectProject(project: Project): void {
    this.selectedProject = project;
    this.displayDetailDialog = true;
    this.resetDocumentForm();
    this.loadProjectDocuments(project.id);
  }

  openCreateDialog(): void {
    const today = new Date().toISOString().split('T')[0];
    const futureDate = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

    this.newProject = {
      name: '',
      description: '',
      objectives: '',
      startDate: today,
      endDate: futureDate,
      visibility: 'PRIVATE'
    };
    this.selectedCustomer = null;
    this.selectedNewMember = null;
    this.newMemberRole = 'PROJECT_MEMBER';
    this.projectMembersToAdd = [];
    this.pendingDocuments = [];
    this.touchedFields = { name: false, description: false, objectives: false, startDate: false, endDate: false };
    this.resetDocumentForm();
    this.displayCreateDialog = true;
  }

  openEditDialog(project: Project): void {
    this.selectedProject = project;
    this.newProject = { ...project };
    this.touchedFields = { name: false, description: false, objectives: false, startDate: false, endDate: false };
    this.resetDocumentForm();
    this.loadProjectDocuments(project.id);
    this.displayEditDialog = true;
  }

  openDeleteDialog(project: Project): void {
    this.selectedProject = project;
    this.displayDeleteDialog = true;
  }

  closeDetailDialog(): void {
    this.displayDetailDialog = false;
    this.resetDocumentForm();
    this.projectDocuments = [];
    this.filteredProjectDocuments = [];
  }

  createProject(): void {
    // Validation complète
    if (!this.newProject.name || !this.newProject.name.trim()) {
      this.messageService.add({
        severity: 'error',
        summary: 'Validation Error',
        detail: 'Project name is required'
      });
      return;
    }

    if (this.newProject.name.trim().length < 3) {
      this.messageService.add({
        severity: 'error',
        summary: 'Validation Error',
        detail: 'Project name must be at least 3 characters'
      });
      return;
    }

    if (!this.newProject.startDate || !this.newProject.endDate) {
      this.messageService.add({
        severity: 'error',
        summary: 'Validation Error',
        detail: 'Start Date and End Date are required'
      });
      return;
    }

    const startDate = new Date(this.newProject.startDate as string);
    const endDate = new Date(this.newProject.endDate as string);
    if (endDate <= startDate) {
      this.messageService.add({
        severity: 'error',
        summary: 'Validation Error',
        detail: 'End Date must be after Start Date'
      });
      return;
    }

    this.loading = true;

    // Pass customer email if selected (for backward compatibility)
    const projectData = {
      ...this.newProject,
      customerEmail: this.selectedCustomer?.email || null
    };

    this.projectService.createProject(projectData)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (createdProject) => {
          console.log('Project created successfully:', createdProject);

          const finishCreation = () => this.completeProjectCreation(
            createdProject,
            this.projectMembersToAdd.length,
            this.pendingDocuments.length
          );

          const addDocumentsAfterMembers = () => {
            if (this.pendingDocuments.length > 0) {
              this.addDocumentsToCreatedProject(createdProject, finishCreation);
            } else {
              finishCreation();
            }
          };

          if (this.projectMembersToAdd.length > 0) {
            this.addMembersToCreatedProject(createdProject, addDocumentsAfterMembers);
          } else {
            addDocumentsAfterMembers();
          }
        },
        error: (error) => {
          console.error('Error creating project:', error);
          this.loading = false;
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: error.error?.message || error.error?.name || 'Failed to create project'
          });
        }
      });
  }

  updateProject(): void {
    if (!this.selectedProject) return;

    if (!this.isFormValid()) {
      this.messageService.add({
        severity: 'error',
        summary: 'Validation Error',
        detail: 'Please fix validation errors'
      });
      return;
    }

    this.loading = true;
    console.log('Updating project with ID:', this.selectedProject.id, 'Data:', this.newProject);

    this.projectService.updateProject(this.selectedProject.id, this.newProject)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (updatedProject) => {
          console.log('Project updated successfully:', updatedProject);
          this.messageService.add({
            severity: 'success',
            summary: 'Success',
            detail: 'Project updated successfully'
          });
          this.displayEditDialog = false;
          this.displayDetailDialog = false;
          this.loading = false;
          setTimeout(() => this.loadProjects(), 500);
        },
        error: (error) => {
          console.error('Error updating project:', error);
          this.loading = false;
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: error.error?.message || 'Failed to update project'
          });
        }
      });
  }

  confirmDelete(): void {
    if (!this.selectedProject) return;

    this.loading = true;
    this.projectService.deleteProject(this.selectedProject.id)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: () => {
          this.messageService.add({
            severity: 'success',
            summary: 'Success',
            detail: 'Project deleted successfully'
          });
          this.displayDeleteDialog = false;
          this.displayDetailDialog = false;
          this.loadProjects();
        },
        error: (error) => {
          console.error('Error deleting project', error);
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: error.error?.message || 'Failed to delete project'
          });
          this.loading = false;
        }
      });
  }

  cancelCreate(): void {
    this.displayCreateDialog = false;
  }

  cancelEdit(): void {
    this.displayEditDialog = false;
  }

  onFieldTouched(fieldName: string): void {
    this.touchedFields[fieldName] = true;
  }

  getProjectNameError(): string {
    if (!this.touchedFields['name']) return '';

    const name = this.newProject.name ? this.newProject.name.trim() : '';

    if (!name) {
      return 'Project name is required';
    }
    if (name.length < 3) {
      return 'Project name must be at least 3 characters';
    }
    if (name.length > 100) {
      return 'Project name cannot exceed 100 characters';
    }
    const pattern = /^[a-zA-Z0-9\s\-_,.:;()&]+$/;
    if (!pattern.test(name)) {
      return 'Invalid characters. Only letters, numbers, and - _ , . : ; ( ) & are allowed';
    }
    return '';
  }

  getDescriptionError(): string {
    if (!this.touchedFields['description']) return '';

    if (this.newProject.description && this.newProject.description.length > 500) {
      return `Description cannot exceed 500 characters (${this.newProject.description.length}/500)`;
    }
    return '';
  }

  getObjectivesError(): string {
    if (!this.touchedFields['objectives']) return '';

    if (this.newProject.objectives && this.newProject.objectives.length > 1000) {
      return `Objectives cannot exceed 1000 characters (${this.newProject.objectives.length}/1000)`;
    }
    return '';
  }

  getStartDateError(): string {
    if (!this.touchedFields['startDate']) return '';

    if (!this.newProject.startDate) {
      return 'Start Date is required';
    }

    const startDate = new Date(this.newProject.startDate as string);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (startDate < today) {
      return 'Start Date must be today or in the future';
    }
    return '';
  }

  getEndDateError(): string {
    if (!this.touchedFields['endDate']) return '';

    if (!this.newProject.endDate) {
      return 'End Date is required';
    }

    if (this.newProject.startDate && this.newProject.endDate) {
      const startDate = new Date(this.newProject.startDate as string);
      const endDate = new Date(this.newProject.endDate as string);

      // Check if end date is after start date
      if (endDate <= startDate) {
        return 'End Date must be after Start Date';
      }

      // Check if start date is in the future
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      if (startDate < today) {
        return 'Start Date must be today or in the future';
      }
    }
    return '';
  }

  isFormValid(): boolean {
    const name = this.newProject.name ? this.newProject.name.trim() : '';
    if (!name || name.length < 3 || name.length > 100) {
      return false;
    }

    const pattern = /^[a-zA-Z0-9\s\-_,.:;()&]+$/;
    if (!pattern.test(name)) {
      return false;
    }

    if (this.newProject.description && this.newProject.description.length > 500) {
      return false;
    }

    if (this.newProject.objectives && this.newProject.objectives.length > 1000) {
      return false;
    }

    if (!this.newProject.startDate || !this.newProject.endDate) {
      return false;
    }

    const startDate = new Date(this.newProject.startDate as string);
    const endDate = new Date(this.newProject.endDate as string);
    if (endDate <= startDate) {
      return false;
    }

    return true;
  }

  getStatusSeverity(status: string): 'success' | 'secondary' | 'info' | 'warning' | 'danger' | 'contrast' | undefined {
    switch (status) {
      case 'COMPLETED':
        return 'success';
      case 'IN_PROGRESS':
        return 'info';
      case 'ON_HOLD':
        return 'warning';
      case 'CANCELLED':
        return 'danger';
      case 'PLANNED':
      default:
        return 'secondary';
    }
  }

  getStatusLabel(status: string): string {
    const labels: { [key: string]: string } = {
      'PLANNED': 'Planned',
      'IN_PROGRESS': 'In Progress',
      'COMPLETED': 'Completed',
      'ON_HOLD': 'On Hold',
      'CANCELLED': 'Cancelled'
    };
    return labels[status] || status;
  }

  // ============ PROGRESS ============

  getProgressLabel(progress: number): string {
    if (progress === 0) return 'not-started';
    if (progress < 25) return 'beginning';
    if (progress < 50) return 'quarter';
    if (progress < 75) return 'half';
    if (progress < 100) return 'almost';
    return 'completed';
  }

  getProgressLabelText(progress: number): string {
    if (progress === 0) return 'Not Started';
    if (progress < 25) return 'Just Started';
    if (progress < 50) return 'In Progress';
    if (progress < 75) return 'Half Done';
    if (progress < 100) return 'Almost Done';
    return 'Completed';
  }

  // ============ PAGINATION ============

  onPageChange(event: any): void {
    this.updatePaginatedProjects(event.first);
  }

  onRowsPerPageChange(): void {
    // Reset to first page when changing rows per page
    this.updatePaginatedProjects(0);
  }

  private updatePaginatedProjects(first: number): void {
    const page = Math.floor(first / this.itemsPerPage);
    const start = page * this.itemsPerPage;
    const end = start + this.itemsPerPage;
    this.paginatedProjects = this.projects.slice(start, end);
  }

  // ============ DOCUMENT MANAGEMENT ============

  private buildEmptyDocumentForm(): ProjectDocumentForm {
    const currentUser = this.authService.getCurrentUser();
    return {
      name: '',
      description: '',
      fileUrl: '',
      type: 'DOCUMENTATION',
      version: '1.0',
      uploadedBy: currentUser ? `${currentUser.firstName} ${currentUser.lastName}`.trim() || currentUser.email : 'system'
    };
  }

  private resetDocumentForm(): void {
    this.documentForm = this.buildEmptyDocumentForm();
    this.editingDocumentId = null;
    this.pendingDocumentEditIndex = null;
    this.documentSearchTerm = '';
    this.documentTypeFilter = '';
  }

  loadProjectDocuments(projectId: number): void {
    this.projectDocumentService.getByProject(projectId)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (documents) => {
          this.projectDocuments = documents || [];
          this.filteredProjectDocuments = [...this.projectDocuments];
        },
        error: (error) => {
          console.error('Error loading project documents', error);
          this.projectDocuments = [];
          this.filteredProjectDocuments = [];
        }
      });
  }

  applyDocumentFilters(): void {
    this.filteredProjectDocuments = [...this.projectDocuments];
  }

  clearDocumentFilters(): void {
    this.documentSearchTerm = '';
    this.documentTypeFilter = '';
    this.applyDocumentFilters();
  }

  startEditDocument(document: ProjectDocument): void {
    this.editingDocumentId = document.id;
    this.pendingDocumentEditIndex = null;
    this.documentForm = {
      name: document.name,
      description: document.description || '',
      fileUrl: document.fileUrl,
      type: document.type,
      version: document.version,
      uploadedBy: document.uploadedBy
    };
  }

  cancelDocumentEdit(): void {
    this.resetDocumentForm();
  }

  startEditPendingDocument(index: number): void {
    const document = this.pendingDocuments[index];
    if (!document) return;
    this.pendingDocumentEditIndex = index;
    this.editingDocumentId = null;
    this.documentForm = { ...document };
  }

  savePendingDocument(): void {
    if (!this.documentForm.name.trim() || !this.documentForm.fileUrl.trim()) {
      this.messageService.add({ severity: 'error', summary: 'Validation Error', detail: 'Document name and file URL are required' });
      return;
    }

    const payload = { ...this.documentForm };

    if (this.pendingDocumentEditIndex !== null) {
      this.pendingDocuments[this.pendingDocumentEditIndex] = payload;
      this.messageService.add({ severity: 'success', summary: 'Success', detail: 'Pending document updated' });
    } else {
      this.pendingDocuments.push(payload);
      this.messageService.add({ severity: 'success', summary: 'Success', detail: 'Pending document added' });
    }

    this.resetDocumentForm();
  }


  removePendingDocument(index: number): void {
    if (index < 0 || index >= this.pendingDocuments.length) return;
    const removed = this.pendingDocuments.splice(index, 1)[0];
    if (this.pendingDocumentEditIndex === index) {
      this.resetDocumentForm();
    }
    this.messageService.add({ severity: 'info', summary: 'Removed', detail: `${removed?.name || 'Document'} removed from pending list` });
  }

  openDocument(url: string): void {
    if (url) {
      window.open(url, '_blank');
    }
  }

  downloadDocument(url: string, fileName: string): void {
    if (!url) return;

    this.messageService.add({
      severity: 'info',
      summary: 'Téléchargement',
      detail: `Préparation de ${fileName}...`
    });

    // Technique robuste : Utilisation de fetch avec détection forcée d'extension
    fetch(url, {
      method: 'GET',
      headers: new Headers({
        'Accept': '*/*'
      })
    })
    .then(response => {
      const contentType = response.headers.get('Content-Type') || '';
      console.log('Content-Type détecté:', contentType);

      const mimeMap: { [key: string]: string } = {
        'application/pdf': '.pdf',
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document': '.docx',
        'application/msword': '.doc',
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': '.xlsx',
        'application/vnd.ms-excel': '.xls',
        'image/jpeg': '.jpg',
        'image/png': '.png',
        'image/gif': '.gif',
        'application/zip': '.zip',
        'text/plain': '.txt',
        'application/json': '.json'
      };

      // 1. Déterminer l'extension basée sur le Content-Type RÉEL
      let extension = '';
      for (const mime in mimeMap) {
        if (contentType.includes(mime)) {
          extension = mimeMap[mime];
          break;
        }
      }

      // 2. Si on ne trouve rien, on regarde l'URL
      if (!extension) {
        const urlMatch = url.match(/\.([0-9a-z]+)(?:[\?#]|$)/i);
        if (urlMatch && urlMatch[1] && !['htm', 'html', 'php', 'aspx'].includes(urlMatch[1].toLowerCase())) {
          extension = '.' + urlMatch[1];
        } else {
          // Par défaut si c'est vraiment inconnu mais qu'on veut éviter .htm
          extension = '.pdf'; // On parie sur le PDF car c'est le plus courant dans les docs projets
        }
      }

      // 3. Forcer le nom final en supprimant toute trace de .htm
      let finalName = fileName || 'document';
      finalName = finalName.replace(/\.(html?|php|aspx|jsp)$/i, '');

      // S'assurer qu'on ne finit pas par l'extension deux fois
      if (!finalName.toLowerCase().endsWith(extension.toLowerCase())) {
        finalName += extension;
      }

      return response.blob().then(blob => ({ blob, finalName }));
    })
    .then(({ blob, finalName }) => {
      // Pour être certain que le type du BLOB n'est pas HTML
      // On peut recréer un blob propre si le type original est suspect
      const cleanBlob = blob.type.includes('html') ? new Blob([blob], { type: 'application/octet-stream' }) : blob;

      const blobUrl = window.URL.createObjectURL(cleanBlob);
      const link = document.createElement('a');
      link.href = blobUrl;
      link.download = finalName;
      document.body.appendChild(link);
      link.click();

      setTimeout(() => {
        document.body.removeChild(link);
        window.URL.revokeObjectURL(blobUrl);
      }, 500);
    })
    .catch(error => {
      console.error('Download failed', error);
      window.open(url, '_blank');
    });
  }

  saveDocument(): void {
    if (!this.selectedProject || !this.documentForm.name.trim() || !this.documentForm.fileUrl.trim()) {
      this.messageService.add({ severity: 'error', summary: 'Validation Error', detail: 'Project, name and file URL are required' });
      return;
    }

    const payload = { ...this.documentForm };

    if (this.editingDocumentId) {
      this.projectDocumentService.update(this.editingDocumentId, this.selectedProject.id, payload)
        .pipe(takeUntil(this.destroy$))
        .subscribe({
          next: () => {
            this.messageService.add({ severity: 'success', summary: 'Success', detail: 'Document updated' });
            this.loadProjectDocuments(this.selectedProject!.id);
            this.resetDocumentForm();
          },
          error: (err) => {
            console.error('Error updating document', err);
            this.messageService.add({ severity: 'error', summary: 'Error', detail: 'Failed to update document' });
          }
        });
    } else {
      this.projectDocumentService.create(this.selectedProject.id, payload)
        .pipe(takeUntil(this.destroy$))
        .subscribe({
          next: () => {
            this.messageService.add({ severity: 'success', summary: 'Success', detail: 'Document added' });
            this.loadProjectDocuments(this.selectedProject!.id);
            this.resetDocumentForm();
          },
          error: (err) => {
            console.error('Error creating document', err);
            this.messageService.add({ severity: 'error', summary: 'Error', detail: 'Failed to create document' });
          }
        });
    }
  }

  deleteDocument(document: ProjectDocument): void {
    this.confirmationService.confirm({
      message: `Are you sure you want to delete "${document.name}"?`,
      header: 'Confirm Deletion',
      icon: 'pi pi-exclamation-triangle',
      accept: () => {
        this.projectDocumentService.delete(document.id)
          .pipe(takeUntil(this.destroy$))
          .subscribe({
            next: () => {
              this.messageService.add({ severity: 'success', summary: 'Success', detail: 'Document deleted' });
              if (this.selectedProject) {
                this.loadProjectDocuments(this.selectedProject.id);
              }
            },
            error: (err) => {
              console.error('Error deleting document', err);
              this.messageService.add({ severity: 'error', summary: 'Error', detail: 'Failed to delete document' });
            }
          });
      }
    });
  }

  // --- Member Management (Existing Project) ---

  hasMembers(): boolean {
    return (this.selectedProject?.members && this.selectedProject.members.length > 0) || false;
  }

  addMember(): void {
    if (!this.selectedProject || !this.selectedNewMember) {
      this.messageService.add({ severity: 'error', summary: 'Error', detail: 'Please select a user' });
      return;
    }

    this.projectService.addProjectMember(this.selectedProject.id, this.selectedNewMember.username, this.newMemberRole)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: () => {
          this.messageService.add({ severity: 'success', summary: 'Success', detail: 'Member added' });
          this.selectedNewMember = null;
          // Refresh project to see new members
          if (this.selectedProject) {
            this.projectService.getProjectById(this.selectedProject.id)
              .subscribe(p => this.selectedProject = p);
          }
        },
        error: (err) => {
          console.error('Error adding member', err);
          this.messageService.add({ severity: 'error', summary: 'Error', detail: 'Failed to add member' });
        }
      });
  }

  removeMember(userId: string): void {
    if (!this.selectedProject) return;

    this.confirmationService.confirm({
      message: 'Are you sure you want to remove this member?',
      header: 'Confirm Removal',
      icon: 'pi pi-exclamation-triangle',
      accept: () => {
        this.projectService.removeProjectMember(this.selectedProject!.id, userId)
          .pipe(takeUntil(this.destroy$))
          .subscribe({
            next: () => {
              this.messageService.add({ severity: 'success', summary: 'Success', detail: 'Member removed' });
              // Refresh project
              this.projectService.getProjectById(this.selectedProject!.id)
                .subscribe(p => this.selectedProject = p);
            },
            error: (err) => {
              console.error('Error removing member', err);
              this.messageService.add({ severity: 'error', summary: 'Error', detail: 'Failed to remove member' });
            }
          });
      }
    });
  }
}

import { Component, OnInit, OnDestroy } from '@angular/core';
import { ProjectService, Project } from '../../../core/services/project.service';
import { AuthService } from '../../../core/services/auth.service';
import { ProjectDocumentService } from '../../../core/services/project-document.service';
import { ProjectDocument, ProjectDocumentForm, ProjectDocumentType } from '../../../core/models/project-document.model';
import { UserService } from '../../../core/services/user.service';
import { MessageService, ConfirmationService } from 'primeng/api';
import { Subject } from 'rxjs';
import { takeUntil } from 'rxjs/operators';

@Component({
  selector: 'app-project-list',
  templateUrl: './project-list.component.html',
  styleUrl: './project-list.component.scss'
})
export class ProjectListComponent implements OnInit, OnDestroy {
  projects: Project[] = [];
  loading = false;
  selectedProject: Project | null = null;
  displayDetailDialog = false;
  displayCreateDialog = false;
  displayEditDialog = false;
  displayDeleteDialog = false;
  private destroy$ = new Subject<void>();

  // Date validation
  today = new Date();

  searchTerm = '';
  statusFilter = '';
  statusOptions = [
    { label: 'All Status', value: '' },
    { label: 'Planned', value: 'PLANNED' },
    { label: 'In Progress', value: 'IN_PROGRESS' },
    { label: 'Completed', value: 'COMPLETED' },
    { label: 'On Hold', value: 'ON_HOLD' },
    { label: 'Cancelled', value: 'CANCELLED' }
  ];

  // Advanced search filters
  advancedSearchActive = false;
  advancedFilters = {
    name: '',
    status: '',
    description: '',
    customer: '',
    createdBy: '',
    minProgress: null,
    maxProgress: null,
    startDateFrom: null,
    startDateTo: null,
    delayedOnly: false,
    sortBy: 'CREATED_DATE',
    sortDirection: 'DESC'
  };

  // Standard/General sort options that everyone knows
  sortOptions = [
    { label: ' Most Recent First', value: 'CREATED_DATE' },
    { label: ' Oldest First', value: 'CREATED_DATE_ASC' },
    { label: ' Project Name (A-Z)', value: 'NAME' },
    { label: ' Project Name (Z-A)', value: 'NAME_DESC' },
    { label: '⏳ Start Date (Earliest)', value: 'START_DATE' },
    { label: '⏳ Start Date (Latest)', value: 'START_DATE_DESC' },
    { label: ' Progress (Highest)', value: 'PROGRESS' },
    { label: ' Progress (Lowest)', value: 'PROGRESS_ASC' },
    { label: ' Recently Updated', value: 'UPDATED_DATE' },
    { label: '⏱️ Status (A-Z)', value: 'STATUS' }
  ];

  sortDirectionOptions = [
    { label: '⬆️ Ascending', value: 'ASC' },
    { label: '⬇️ Descending', value: 'DESC' }
  ];

  newProject: Partial<Project> = {
    name: '',
    description: '',
    objectives: '',
    startDate: new Date().toISOString().split('T')[0],
    endDate: '',
    visibility: 'PRIVATE'
  };

  touchedFields: { [key: string]: boolean } = {
    name: false,
    description: false,
    objectives: false,
    startDate: false,
    endDate: false
  };

  // Pagination
  private currentPage = 1;
  itemsPerPage = 6;
  rowsPerPageOptions = [6, 10, 20, 30];
  paginatedProjects: Project[] = [];
  totalRecords = 0;
  availableRoles = [
    { label: 'Project Member', value: 'PROJECT_MEMBER' },
    { label: 'Project Manager', value: 'PROJECT_MANAGER' },
    { label: 'Customer', value: 'CUSTOMER' }
  ];

  // Member management
  newMemberEmail = '';
  newMemberRole = 'PROJECT_MEMBER';
  selectedNewMember: any = null;
  allUsers: any[] = [];
  filteredUsers: any[] = [];
  projectMembersToAdd: any[] = [];

  // Customer selection
  selectedCustomer: any = null;
  allCustomers: any[] = [];
  filteredCustomers: any[] = [];

  // Document management
  projectDocuments: ProjectDocument[] = [];
  filteredProjectDocuments: ProjectDocument[] = [];
  documentSearchTerm = '';
  documentTypeFilter = '';
  editingDocumentId: number | null = null;
  pendingDocumentEditIndex: number | null = null;
  pendingDocuments: ProjectDocumentForm[] = [];
  projectDocumentTypes: { label: string; value: ProjectDocumentType | '' }[] = [
    { label: 'All Types', value: '' },
    { label: 'Cahier des charges', value: 'CAHIER_CHARGES' },
    { label: 'Specifications', value: 'SPECIFICATIONS' },
    { label: 'Architecture', value: 'ARCHITECTURE' },
    { label: 'Design', value: 'DESIGN' },
    { label: 'Test plan', value: 'TEST_PLAN' },
    { label: 'Documentation', value: 'DOCUMENTATION' },
    { label: 'Release notes', value: 'RELEASE_NOTES' },
    { label: 'Other', value: 'OTHER' }
  ];
  projectDocumentTypeOptions = this.projectDocumentTypes.filter(option => option.value !== '');
  documentForm!: ProjectDocumentForm;

   constructor(
     private projectService: ProjectService,
     private projectDocumentService: ProjectDocumentService,
     public authService: AuthService,
     private userService: UserService,
     private messageService: MessageService,
     private confirmationService: ConfirmationService
   ) {
     this.documentForm = this.buildEmptyDocumentForm();
   }

  ngOnInit(): void {
    this.loadProjects();
    this.loadCustomers();
    this.loadUsers();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  loadProjects(): void {
    this.loading = true;
    const currentUser = this.authService.getCurrentUser();

    if (!currentUser) {
      this.messageService.add({
        severity: 'error',
        summary: 'Error',
        detail: 'User not authenticated'
      });
      this.loading = false;
      return;
    }

    this.projectService.getProjectsByUser(currentUser.id.toString())
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (data) => {
          this.projects = data;
          this.totalRecords = data.length;
          this.updatePaginatedProjects(0);
          this.loading = false;
        },
        error: (error) => {
          console.error('Error loading projects', error);
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: 'Failed to load projects'
          });
          this.loading = false;
        }
      });
  }

  performSearch(): void {
    if (!this.searchTerm && !this.statusFilter) {
      this.loadProjects();
      return;
    }

    this.loading = true;
    this.projectService.searchProjects(this.searchTerm, this.statusFilter)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (data) => {
          this.projects = data;
          this.totalRecords = data.length;
          this.updatePaginatedProjects(0);
          this.loading = false;
        },
        error: (error) => {
          console.error('Error searching projects', error);
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: 'Failed to search projects'
          });
          this.loading = false;
        }
      });
  }

  toggleAdvancedSearch(): void {
    this.advancedSearchActive = !this.advancedSearchActive;
    if (!this.advancedSearchActive) {
      this.resetAdvancedFilters();
    }
  }

  performAdvancedSearch(): void {
    this.loading = true;
    const filters = {
      ...this.advancedFilters,
      minProgress: this.advancedFilters.minProgress ? this.advancedFilters.minProgress / 100 : null,
      maxProgress: this.advancedFilters.maxProgress ? this.advancedFilters.maxProgress / 100 : null
    };

    this.projectService.advancedSearchProjects(filters)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (data) => {
          this.projects = data;
          this.totalRecords = data.length;
          this.updatePaginatedProjects(0);
          this.loading = false;
          this.messageService.add({
            severity: 'success',
            summary: 'Success',
            detail: `Found ${data.length} project(s)`
          });
        },
        error: (error) => {
          console.error('Error searching projects', error);
          this.loading = false;
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: 'Failed to perform advanced search'
          });
        }
      });
  }

  resetAdvancedFilters(): void {
    this.advancedFilters = {
      name: '',
      status: '',
      description: '',
      customer: '',
      createdBy: '',
      minProgress: null,
      maxProgress: null,
      startDateFrom: null,
      startDateTo: null,
      delayedOnly: false,
      sortBy: 'CREATED_DATE',
      sortDirection: 'DESC'
    };
    this.loadProjects();
  }

  onStatusFilterChange(): void {
    this.performSearch();
  }

  clearFilters(): void {
    this.searchTerm = '';
    this.statusFilter = '';
    this.loadProjects();
  }

    /**
     * Load customers from user service or mock data
     */
    loadCustomers(): void {
      // Load customers from backend using the /all endpoint (no pagination)
      this.userService.getAllUsersList()
        .pipe(takeUntil(this.destroy$))
        .subscribe({
          next: (usersList: any[]) => {
            console.log('Customers response:', usersList);

            // Convert to the format we need
            this.allCustomers = usersList
              .map((user: any) => {
                // Ensure firstName and lastName are always defined
                const firstName = (user.firstName || user.name || user.username || 'User').toString().trim();
                const lastName = (user.lastName || '').toString().trim();
                const fullName = `${firstName} ${lastName}`.trim();

                return {
                  id: user.id,
                  username: user.username,
                  email: user.email,
                  firstName: firstName,
                  lastName: lastName,
                  avatar: user.avatarUrl || user.avatar,
                  fullName: fullName
                };
              });

            this.filteredCustomers = [...this.allCustomers];

            // Sort by username
            this.filteredCustomers.sort((a, b) => a.username.localeCompare(b.username));
          },
          error: (error) => {
            console.error('Error loading customers:', error);
            // Fallback to empty list on error
            this.allCustomers = [];
            this.filteredCustomers = [];
          }
        });
    }

  /**
   * Filter customers based on search term (username)
   */
  filterCustomers(event: any): void {
    const query = event.query;
    this.filteredCustomers = this.allCustomers.filter(customer =>
      customer.username.toLowerCase().includes(query.toLowerCase()) ||
      customer.email.toLowerCase().includes(query.toLowerCase())
    );
    // Sort by username
    this.filteredCustomers.sort((a, b) => a.username.localeCompare(b.username));
  }

  /**
   * Handle customer selection
   */
  onCustomerSelect(event: any): void {
    this.selectedCustomer = event;
  }

   /**
    * Load users from user service or mock data
    * Excludes the currently logged-in user
    */
   loadUsers(): void {
     const currentUser = this.authService.getCurrentUser();

     // Load users from backend using the /all endpoint (no pagination)
     this.userService.getAllUsersList()
       .pipe(takeUntil(this.destroy$))
       .subscribe({
         next: (usersList: any[]) => {
           // Debug: log what we receive
           console.log('Users response:', usersList);

           // Convert to the format we need and filter out current user
           this.allUsers = usersList
             .map((user: any) => {
               console.log('Processing user:', user);

               // Ensure firstName and lastName are always defined
               const firstName = (user.firstName || user.name || user.username || 'User').toString().trim();
               const lastName = (user.lastName || '').toString().trim();
               const fullName = `${firstName} ${lastName}`.trim();

               const mappedUser = {
                 id: user.id,
                 username: user.username,
                 email: user.email,
                 firstName: firstName,
                 lastName: lastName,
                 avatar: user.avatarUrl || user.avatar,
                 fullName: fullName
               };

               console.log('Mapped user:', mappedUser);
               return mappedUser;
             })
             .filter((user: any) => user.id !== currentUser?.id);

           console.log('All users after mapping:', this.allUsers);

           this.filteredUsers = [...this.allUsers];

           // Sort by first name
           this.filteredUsers.sort((a, b) => a.firstName.localeCompare(b.firstName));
         },
         error: (error) => {
           console.error('Error loading users:', error);
           // Fallback to empty list on error
           this.allUsers = [];
           this.filteredUsers = [];
           this.messageService.add({
             severity: 'warn',
             summary: 'Warning',
             detail: 'Could not load users list from server'
           });
         }
       });
   }

  /**
   * Filter users based on search term (firstName, lastName, username, or email)
   */
  filterUsers(event: any): void {
    const query = event.query.toLowerCase();
    this.filteredUsers = this.allUsers.filter(user =>
      user.firstName.toLowerCase().includes(query) ||
      user.lastName.toLowerCase().includes(query) ||
      user.username.toLowerCase().includes(query) ||
      user.email.toLowerCase().includes(query)
    );
    // Sort by first name
    this.filteredUsers.sort((a, b) => a.firstName.localeCompare(b.firstName));
  }

   /**
    * Get display name for a user
    */
   getUserDisplayName(user: any): string {
     if (!user) return '';
     const firstName = user.firstName || user.name || user.username || '';
     const lastName = user.lastName || '';
     const fullName = `${firstName} ${lastName}`.trim();
     return fullName || user.username || user.email || 'User';
   }

   /**
    * Handle member selection
    */
   onMemberSelect(event: any): void {
     this.selectedNewMember = event?.value ?? event;
   }

   /**
    * Add member to the temporary list during project creation
    */
   addMemberToCreateForm(): void {
     if (!this.selectedNewMember) {
       this.messageService.add({
         severity: 'error',
         summary: 'Error',
         detail: 'Please select a user'
       });
       return;
     }

     // Check if member already in the list
     const exists = this.projectMembersToAdd.some(m => m.id === this.selectedNewMember.id);
     if (exists) {
       this.messageService.add({
         severity: 'warning',
         summary: 'Warning',
         detail: 'This user is already in the members list'
       });
       return;
     }

     // Add member to the list
     this.projectMembersToAdd.push({
       id: this.selectedNewMember.id,
       firstName: this.selectedNewMember.firstName,
       lastName: this.selectedNewMember.lastName,
       username: this.selectedNewMember.username,
       email: this.selectedNewMember.email,
       role: this.newMemberRole,
       fullName: this.selectedNewMember.fullName
     });

     this.messageService.add({
       severity: 'success',
       summary: 'Success',
       detail: `${this.selectedNewMember.fullName} added to members list`
     });

     // Reset selections
     this.selectedNewMember = null;
     this.newMemberRole = 'PROJECT_MEMBER';
   }

  /**
   * Remove member from the temporary list during project creation
   */
  removeMemberFromCreateForm(member: any): void {
    this.projectMembersToAdd = this.projectMembersToAdd.filter(m => m.id !== member.id);
    this.messageService.add({
      severity: 'info',
      summary: 'Removed',
      detail: `${member.firstName} removed from members list`
    });
  }

   /**
    * Add members to the created project
    */
   private addMembersToCreatedProject(createdProject: any, onComplete: () => void): void {
      let membersAdded = 0;
      let membersTotal = this.projectMembersToAdd.length;

      if (membersTotal === 0) {
        onComplete();
        return;
      }

      this.projectMembersToAdd.forEach((member) => {
        // Use username instead of ID to match backend expectation
        this.projectService.addProjectMember(createdProject.id, member.username, member.role)
          .pipe(takeUntil(this.destroy$))
          .subscribe({
            next: () => {
              membersAdded++;
              if (membersAdded === membersTotal) {
                onComplete();
              }
            },
            error: (error) => {
              console.error(`Error adding member ${member.firstName}:`, error);
              membersAdded++;
              if (membersAdded === membersTotal) {
                onComplete();
              }
            }
          });
      });
    }

   private addDocumentsToCreatedProject(createdProject: any, onComplete: () => void): void {
     let documentsAdded = 0;
     const documentsTotal = this.pendingDocuments.length;

     if (documentsTotal === 0) {
       onComplete();
       return;
     }

     this.pendingDocuments.forEach((document) => {
       this.projectDocumentService.create(createdProject.id, document)
         .pipe(takeUntil(this.destroy$))
         .subscribe({
           next: () => {
             documentsAdded++;
             if (documentsAdded === documentsTotal) {
               onComplete();
             }
           },
           error: (error) => {
             console.error('Error adding document to created project:', error);
             documentsAdded++;
             if (documentsAdded === documentsTotal) {
               onComplete();
             }
           }
         });
     });
   }

   /**
    * Complete project creation process
    */
   private completeProjectCreation(createdProject: any, membersCount?: number, documentsCount?: number): void {
     let detail = `Project created successfully`;
     if (membersCount && membersCount > 0) {
       detail += ` with ${membersCount} member(s) added`;
     }
     if (documentsCount && documentsCount > 0) {
       detail += `${membersCount && membersCount > 0 ? ' and' : ' with'} ${documentsCount} document(s) added`;
     }

     this.messageService.add({
       severity: 'success',
       summary: 'Success',
       detail: detail
     });

     this.displayCreateDialog = false;
     this.selectedCustomer = null;
     this.projectMembersToAdd = [];
     this.pendingDocuments = [];
     this.resetDocumentForm();
     this.loading = false;

     // Reload projects after a short delay to ensure backend has persisted
     setTimeout(() => this.loadProjects(), 500);
  }

  isProjectManager(project: Project): boolean {
    const currentUser = this.authService.getCurrentUser();
    return currentUser !== null && project.projectManagerId === currentUser.id.toString();
  }

  canEdit(project: Project): boolean {
    return this.isProjectManager(project);
  }

  canDelete(project: Project): boolean {
    return this.isProjectManager(project) && project.status !== 'COMPLETED';
  }

  formatDate(date: string | undefined): string {
    if (!date) return '-';
    return new Date(date).toLocaleDateString();
  }

  getDocumentTypeLabel(type: string): string {
    const labels: Record<string, string> = {
      CAHIER_CHARGES: 'Cahier des charges',
      SPECIFICATIONS: 'Specifications',
      ARCHITECTURE: 'Architecture',
      DESIGN: 'Design',
      TEST_PLAN: 'Test plan',
      DOCUMENTATION: 'Documentation',
      RELEASE_NOTES: 'Release notes',
      OTHER: 'Other'
    };
    return labels[type] || type;
  }

  // Convert string date to Date object for calendar minDate
  getStartDateAsDate(): Date | null {
    if (!this.newProject.startDate) return null;
    return new Date(this.newProject.startDate as string);
  }

  onSelectProject(project: Project): void {
    this.selectedProject = project;
    this.displayDetailDialog = true;
    this.resetDocumentForm();
    this.loadProjectDocuments(project.id);
  }

  openCreateDialog(): void {
    const today = new Date().toISOString().split('T')[0];
    const futureDate = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

    this.newProject = {
      name: '',
      description: '',
      objectives: '',
      startDate: today,
      endDate: futureDate,
      visibility: 'PRIVATE'
    };
    this.selectedCustomer = null;
    this.selectedNewMember = null;
    this.newMemberRole = 'PROJECT_MEMBER';
    this.projectMembersToAdd = [];
    this.pendingDocuments = [];
    this.touchedFields = { name: false, description: false, objectives: false, startDate: false, endDate: false };
    this.resetDocumentForm();
    this.displayCreateDialog = true;
  }

  openEditDialog(project: Project): void {
    this.selectedProject = project;
    this.newProject = { ...project };
    this.touchedFields = { name: false, description: false, objectives: false, startDate: false, endDate: false };
    this.resetDocumentForm();
    this.loadProjectDocuments(project.id);
    this.displayEditDialog = true;
  }

  openDeleteDialog(project: Project): void {
    this.selectedProject = project;
    this.displayDeleteDialog = true;
  }

  closeDetailDialog(): void {
    this.displayDetailDialog = false;
    this.resetDocumentForm();
    this.projectDocuments = [];
    this.filteredProjectDocuments = [];
  }

  createProject(): void {
    // Validation complète
    if (!this.newProject.name || !this.newProject.name.trim()) {
      this.messageService.add({
        severity: 'error',
        summary: 'Validation Error',
        detail: 'Project name is required'
      });
      return;
    }

    if (this.newProject.name.trim().length < 3) {
      this.messageService.add({
        severity: 'error',
        summary: 'Validation Error',
        detail: 'Project name must be at least 3 characters'
      });
      return;
    }

    if (!this.newProject.startDate || !this.newProject.endDate) {
      this.messageService.add({
        severity: 'error',
        summary: 'Validation Error',
        detail: 'Start Date and End Date are required'
      });
      return;
    }

    const startDate = new Date(this.newProject.startDate as string);
    const endDate = new Date(this.newProject.endDate as string);
    if (endDate <= startDate) {
      this.messageService.add({
        severity: 'error',
        summary: 'Validation Error',
        detail: 'End Date must be after Start Date'
      });
      return;
    }

    this.loading = true;

    // Pass customer email if selected (for backward compatibility)
    const projectData = {
      ...this.newProject,
      customerEmail: this.selectedCustomer?.email || null
    };

    this.projectService.createProject(projectData)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (createdProject) => {
          console.log('Project created successfully:', createdProject);

          const finishCreation = () => this.completeProjectCreation(
            createdProject,
            this.projectMembersToAdd.length,
            this.pendingDocuments.length
          );

          const addDocumentsAfterMembers = () => {
            if (this.pendingDocuments.length > 0) {
              this.addDocumentsToCreatedProject(createdProject, finishCreation);
            } else {
              finishCreation();
            }
          };

          if (this.projectMembersToAdd.length > 0) {
            this.addMembersToCreatedProject(createdProject, addDocumentsAfterMembers);
          } else {
            addDocumentsAfterMembers();
          }
        },
        error: (error) => {
          console.error('Error creating project:', error);
          this.loading = false;
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: error.error?.message || error.error?.name || 'Failed to create project'
          });
        }
      });
  }

  updateProject(): void {
    if (!this.selectedProject) return;

    if (!this.isFormValid()) {
      this.messageService.add({
        severity: 'error',
        summary: 'Validation Error',
        detail: 'Please fix validation errors'
      });
      return;
    }

    this.loading = true;
    console.log('Updating project with ID:', this.selectedProject.id, 'Data:', this.newProject);

    this.projectService.updateProject(this.selectedProject.id, this.newProject)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (updatedProject) => {
          console.log('Project updated successfully:', updatedProject);
          this.messageService.add({
            severity: 'success',
            summary: 'Success',
            detail: 'Project updated successfully'
          });
          this.displayEditDialog = false;
          this.displayDetailDialog = false;
          this.loading = false;
          setTimeout(() => this.loadProjects(), 500);
        },
        error: (error) => {
          console.error('Error updating project:', error);
          this.loading = false;
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: error.error?.message || 'Failed to update project'
          });
        }
      });
  }

  confirmDelete(): void {
    if (!this.selectedProject) return;

    this.loading = true;
    this.projectService.deleteProject(this.selectedProject.id)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: () => {
          this.messageService.add({
            severity: 'success',
            summary: 'Success',
            detail: 'Project deleted successfully'
          });
          this.displayDeleteDialog = false;
          this.displayDetailDialog = false;
          this.loadProjects();
        },
        error: (error) => {
          console.error('Error deleting project', error);
          this.messageService.add({
            severity: 'error',
            summary: 'Error',
            detail: error.error?.message || 'Failed to delete project'
          });
          this.loading = false;
        }
      });
  }

  cancelCreate(): void {
    this.displayCreateDialog = false;
  }

  cancelEdit(): void {
    this.displayEditDialog = false;
  }

  onFieldTouched(fieldName: string): void {
    this.touchedFields[fieldName] = true;
  }

  getProjectNameError(): string {
    if (!this.touchedFields['name']) return '';

    const name = this.newProject.name ? this.newProject.name.trim() : '';

    if (!name) {
      return 'Project name is required';
    }
    if (name.length < 3) {
      return 'Project name must be at least 3 characters';
    }
    if (name.length > 100) {
      return 'Project name cannot exceed 100 characters';
    }
    const pattern = /^[a-zA-Z0-9\s\-_,.:;()&]+$/;
    if (!pattern.test(name)) {
      return 'Invalid characters. Only letters, numbers, and - _ , . : ; ( ) & are allowed';
    }
    return '';
  }

  getDescriptionError(): string {
    if (!this.touchedFields['description']) return '';

    if (this.newProject.description && this.newProject.description.length > 500) {
      return `Description cannot exceed 500 characters (${this.newProject.description.length}/500)`;
    }
    return '';
  }

  getObjectivesError(): string {
    if (!this.touchedFields['objectives']) return '';

    if (this.newProject.objectives && this.newProject.objectives.length > 1000) {
      return `Objectives cannot exceed 1000 characters (${this.newProject.objectives.length}/1000)`;
    }
    return '';
  }

  getStartDateError(): string {
    if (!this.touchedFields['startDate']) return '';

    if (!this.newProject.startDate) {
      return 'Start Date is required';
    }

    const startDate = new Date(this.newProject.startDate as string);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (startDate < today) {
      return 'Start Date must be today or in the future';
    }
    return '';
  }

  getEndDateError(): string {
    if (!this.touchedFields['endDate']) return '';

    if (!this.newProject.endDate) {
      return 'End Date is required';
    }

    if (this.newProject.startDate && this.newProject.endDate) {
      const startDate = new Date(this.newProject.startDate as string);
      const endDate = new Date(this.newProject.endDate as string);

      // Check if end date is after start date
      if (endDate <= startDate) {
        return 'End Date must be after Start Date';
      }

      // Check if start date is in the future
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      if (startDate < today) {
        return 'Start Date must be today or in the future';
      }
    }
    return '';
  }

  isFormValid(): boolean {
    const name = this.newProject.name ? this.newProject.name.trim() : '';
    if (!name || name.length < 3 || name.length > 100) {
      return false;
    }

    const pattern = /^[a-zA-Z0-9\s\-_,.:;()&]+$/;
    if (!pattern.test(name)) {
      return false;
    }

    if (this.newProject.description && this.newProject.description.length > 500) {
      return false;
    }

    if (this.newProject.objectives && this.newProject.objectives.length > 1000) {
      return false;
    }

    if (!this.newProject.startDate || !this.newProject.endDate) {
      return false;
    }

    const startDate = new Date(this.newProject.startDate as string);
    const endDate = new Date(this.newProject.endDate as string);
    if (endDate <= startDate) {
      return false;
    }

    return true;
  }

  getStatusSeverity(status: string): 'success' | 'secondary' | 'info' | 'warning' | 'danger' | 'contrast' | undefined {
    switch (status) {
      case 'COMPLETED':
        return 'success';
      case 'IN_PROGRESS':
        return 'info';
      case 'ON_HOLD':
        return 'warning';
      case 'CANCELLED':
        return 'danger';
      case 'PLANNED':
      default:
        return 'secondary';
    }
  }

  getStatusLabel(status: string): string {
    const labels: { [key: string]: string } = {
      'PLANNED': 'Planned',
      'IN_PROGRESS': 'In Progress',
      'COMPLETED': 'Completed',
      'ON_HOLD': 'On Hold',
      'CANCELLED': 'Cancelled'
    };
    return labels[status] || status;
  }

  // ============ PROGRESS ============

  getProgressLabel(progress: number): string {
    if (progress === 0) return 'not-started';
    if (progress < 25) return 'beginning';
    if (progress < 50) return 'quarter';
    if (progress < 75) return 'half';
    if (progress < 100) return 'almost';
    return 'completed';
  }

  getProgressLabelText(progress: number): string {
    if (progress === 0) return 'Not Started';
    if (progress < 25) return 'Just Started';
    if (progress < 50) return 'In Progress';
    if (progress < 75) return 'Half Done';
    if (progress < 100) return 'Almost Done';
    return 'Completed';
  }

  // ============ PAGINATION ============

  onPageChange(event: any): void {
    this.updatePaginatedProjects(event.first);
  }

  onRowsPerPageChange(): void {
    // Reset to first page when changing rows per page
    this.updatePaginatedProjects(0);
  }

  private updatePaginatedProjects(first: number): void {
    const page = Math.floor(first / this.itemsPerPage);
    const start = page * this.itemsPerPage;
    const end = start + this.itemsPerPage;
    this.paginatedProjects = this.projects.slice(start, end);
  }

  // ============ DOCUMENT MANAGEMENT ============

  private buildEmptyDocumentForm(): ProjectDocumentForm {
    const currentUser = this.authService.getCurrentUser();
    return {
      name: '',
      description: '',
      fileUrl: '',
      type: 'DOCUMENTATION',
      version: '1.0',
      uploadedBy: currentUser ? `${currentUser.firstName} ${currentUser.lastName}`.trim() || currentUser.email : 'system'
    };
  }

  private resetDocumentForm(): void {
    this.documentForm = this.buildEmptyDocumentForm();
    this.editingDocumentId = null;
    this.pendingDocumentEditIndex = null;
    this.documentSearchTerm = '';
    this.documentTypeFilter = '';
  }

  loadProjectDocuments(projectId: number): void {
    this.projectDocumentService.getByProject(projectId)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: (documents) => {
          this.projectDocuments = documents || [];
          this.filteredProjectDocuments = [...this.projectDocuments];
        },
        error: (error) => {
          console.error('Error loading project documents', error);
          this.projectDocuments = [];
          this.filteredProjectDocuments = [];
        }
      });
  }

  applyDocumentFilters(): void {
    this.filteredProjectDocuments = [...this.projectDocuments];
  }

  clearDocumentFilters(): void {
    this.documentSearchTerm = '';
    this.documentTypeFilter = '';
    this.applyDocumentFilters();
  }

  startEditDocument(document: ProjectDocument): void {
    this.editingDocumentId = document.id;
    this.pendingDocumentEditIndex = null;
    this.documentForm = {
      name: document.name,
      description: document.description || '',
      fileUrl: document.fileUrl,
      type: document.type,
      version: document.version,
      uploadedBy: document.uploadedBy
    };
  }

  cancelDocumentEdit(): void {
    this.resetDocumentForm();
  }

  startEditPendingDocument(index: number): void {
    const document = this.pendingDocuments[index];
    if (!document) return;
    this.pendingDocumentEditIndex = index;
    this.editingDocumentId = null;
    this.documentForm = { ...document };
  }

  savePendingDocument(): void {
    if (!this.documentForm.name.trim() || !this.documentForm.fileUrl.trim()) {
      this.messageService.add({ severity: 'error', summary: 'Validation Error', detail: 'Document name and file URL are required' });
      return;
    }

    const payload = { ...this.documentForm };

    if (this.pendingDocumentEditIndex !== null) {
      this.pendingDocuments[this.pendingDocumentEditIndex] = payload;
      this.messageService.add({ severity: 'success', summary: 'Success', detail: 'Pending document updated' });
    } else {
      this.pendingDocuments.push(payload);
      this.messageService.add({ severity: 'success', summary: 'Success', detail: 'Pending document added' });
    }

    this.resetDocumentForm();
  }


  removePendingDocument(index: number): void {
    if (index < 0 || index >= this.pendingDocuments.length) return;
    const removed = this.pendingDocuments.splice(index, 1)[0];
    if (this.pendingDocumentEditIndex === index) {
      this.resetDocumentForm();
    }
    this.messageService.add({ severity: 'info', summary: 'Removed', detail: `${removed?.name || 'Document'} removed from pending list` });
  }

  openDocument(url: string): void {
    if (!url) return;

    // Si c'est un lien Google Drive, on s'assure qu'il s'ouvre dans un nouvel onglet
    // car le téléchargement direct via Blob échouera souvent à cause du CORS ou de l'authentification Drive.
    window.open(url, '_blank');
  }

  downloadDocument(url: string, fileName: string): void {
    if (!url) return;

    this.messageService.add({
      severity: 'info',
      summary: 'Téléchargement',
      detail: `Accès au document : ${fileName}...`
    });

    // Cas particulier Google Drive : conversion du lien de visualisation en lien de téléchargement direct
    let directUrl = url;
    if (url.includes('drive.google.com')) {
      const fileIdMatch = url.match(/\/d\/([a-zA-Z0-9_-]+)/);
      if (fileIdMatch && fileIdMatch[1]) {
        // Lien de téléchargement direct pour Google Drive
        directUrl = `https://drive.google.com/uc?export=download&id=${fileIdMatch[1]}`;
        // Pour Google Drive, on ouvre simplement le lien de téléchargement direct
        window.open(directUrl, '_blank');
        return;
      }
    }

    // Pour les autres URLs, on tente le fetch ou on ouvre directement si ça échoue
    fetch(url, {
      method: 'GET',
      mode: 'cors'
    })
    .then(response => {
      if (!response.ok) throw new Error('CORS or Network error');

      const contentType = response.headers.get('Content-Type') || '';
      console.log('Content-Type détecté:', contentType);

      const mimeMap: { [key: string]: string } = {
        'application/pdf': '.pdf',
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document': '.docx',
        'application/msword': '.doc',
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': '.xlsx',
        'application/vnd.ms-excel': '.xls',
        'image/jpeg': '.jpg',
        'image/png': '.png',
        'image/gif': '.gif',
        'application/zip': '.zip',
        'text/plain': '.txt',
        'application/json': '.json'
      };

      // 1. Déterminer l'extension basée sur le Content-Type RÉEL
      let extension = '';
      for (const mime in mimeMap) {
        if (contentType.includes(mime)) {
          extension = mimeMap[mime];
          break;
        }
      }

      // 2. Si on ne trouve rien, on regarde l'URL
      if (!extension) {
        const urlMatch = url.match(/\.([0-9a-z]+)(?:[\?#]|$)/i);
        if (urlMatch && urlMatch[1] && !['htm', 'html', 'php', 'aspx'].includes(urlMatch[1].toLowerCase())) {
          extension = '.' + urlMatch[1];
        } else {
          // Par défaut si c'est vraiment inconnu mais qu'on veut éviter .htm
          extension = '.pdf'; // On parie sur le PDF car c'est le plus courant dans les docs projets
        }
      }

      // 3. Forcer le nom final en supprimant toute trace de .htm
      let finalName = fileName || 'document';
      finalName = finalName.replace(/\.(html?|php|aspx|jsp)$/i, '');

      // S'assurer qu'on ne finit pas par l'extension deux fois
      if (!finalName.toLowerCase().endsWith(extension.toLowerCase())) {
        finalName += extension;
      }

      return response.blob().then(blob => ({ blob, finalName }));
    })
    .then(({ blob, finalName }) => {
      // Pour être certain que le type du BLOB n'est pas HTML
      // On peut recréer un blob propre si le type original est suspect
      const cleanBlob = blob.type.includes('html') ? new Blob([blob], { type: 'application/octet-stream' }) : blob;

      const blobUrl = window.URL.createObjectURL(cleanBlob);
      const link = document.createElement('a');
      link.href = blobUrl;
      link.download = finalName;
      document.body.appendChild(link);
      link.click();

      setTimeout(() => {
        document.body.removeChild(link);
        window.URL.revokeObjectURL(blobUrl);
      }, 500);
    })
    .catch(error => {
      console.warn('Direct fetch failed, falling back to window.open', error);
      // Fallback ultime : ouvrir le lien original
      window.open(url, '_blank');
    });
  }

  saveDocument(): void {
    if (!this.selectedProject || !this.documentForm.name.trim() || !this.documentForm.fileUrl.trim()) {
      this.messageService.add({ severity: 'error', summary: 'Validation Error', detail: 'Project, name and file URL are required' });
      return;
    }

    const payload = { ...this.documentForm };

    if (this.editingDocumentId) {
      this.projectDocumentService.update(this.editingDocumentId, this.selectedProject.id, payload)
        .pipe(takeUntil(this.destroy$))
        .subscribe({
          next: () => {
            this.messageService.add({ severity: 'success', summary: 'Success', detail: 'Document updated' });
            this.loadProjectDocuments(this.selectedProject!.id);
            this.resetDocumentForm();
          },
          error: (err) => {
            console.error('Error updating document', err);
            this.messageService.add({ severity: 'error', summary: 'Error', detail: 'Failed to update document' });
          }
        });
    } else {
      this.projectDocumentService.create(this.selectedProject.id, payload)
        .pipe(takeUntil(this.destroy$))
        .subscribe({
          next: () => {
            this.messageService.add({ severity: 'success', summary: 'Success', detail: 'Document added' });
            this.loadProjectDocuments(this.selectedProject!.id);
            this.resetDocumentForm();
          },
          error: (err) => {
            console.error('Error creating document', err);
            this.messageService.add({ severity: 'error', summary: 'Error', detail: 'Failed to create document' });
          }
        });
    }
  }

  deleteDocument(document: ProjectDocument): void {
    this.confirmationService.confirm({
      message: `Are you sure you want to delete "${document.name}"?`,
      header: 'Confirm Deletion',
      icon: 'pi pi-exclamation-triangle',
      accept: () => {
        this.projectDocumentService.delete(document.id)
          .pipe(takeUntil(this.destroy$))
          .subscribe({
            next: () => {
              this.messageService.add({ severity: 'success', summary: 'Success', detail: 'Document deleted' });
              if (this.selectedProject) {
                this.loadProjectDocuments(this.selectedProject.id);
              }
            },
            error: (err) => {
              console.error('Error deleting document', err);
              this.messageService.add({ severity: 'error', summary: 'Error', detail: 'Failed to delete document' });
            }
          });
      }
    });
  }

  // --- Member Management (Existing Project) ---

  hasMembers(): boolean {
    return (this.selectedProject?.members && this.selectedProject.members.length > 0) || false;
  }

  addMember(): void {
    if (!this.selectedProject || !this.selectedNewMember) {
      this.messageService.add({ severity: 'error', summary: 'Error', detail: 'Please select a user' });
      return;
    }

    this.projectService.addProjectMember(this.selectedProject.id, this.selectedNewMember.username, this.newMemberRole)
      .pipe(takeUntil(this.destroy$))
      .subscribe({
        next: () => {
          this.messageService.add({ severity: 'success', summary: 'Success', detail: 'Member added' });
          this.selectedNewMember = null;
          // Refresh project to see new members
          if (this.selectedProject) {
            this.projectService.getProjectById(this.selectedProject.id)
              .subscribe(p => this.selectedProject = p);
          }
        },
        error: (err) => {
          console.error('Error adding member', err);
          this.messageService.add({ severity: 'error', summary: 'Error', detail: 'Failed to add member' });
        }
      });
  }

  removeMember(userId: string): void {
    if (!this.selectedProject) return;

    this.confirmationService.confirm({
      message: 'Are you sure you want to remove this member?',
      header: 'Confirm Removal',
      icon: 'pi pi-exclamation-triangle',
      accept: () => {
        this.projectService.removeProjectMember(this.selectedProject!.id, userId)
          .pipe(takeUntil(this.destroy$))
          .subscribe({
            next: () => {
              this.messageService.add({ severity: 'success', summary: 'Success', detail: 'Member removed' });
              // Refresh project
              this.projectService.getProjectById(this.selectedProject!.id)
                .subscribe(p => this.selectedProject = p);
            },
            error: (err) => {
              console.error('Error removing member', err);
              this.messageService.add({ severity: 'error', summary: 'Error', detail: 'Failed to remove member' });
            }
          });
      }
    });
  }
}
